import{_ as t,o,c as r,a3 as a}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Vendors Module","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Vendors Module | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/vendors-overview"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Vendors Module | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/vendors-overview"}]]},"headers":[],"relativePath":"user-guide/vendors-overview.md","filePath":"user-guide/vendors-overview.md","lastUpdated":1786752936000}'),i={name:"user-guide/vendors-overview.md"};function s(d,e,n,l,c,p){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="vendors-module" tabindex="-1">Vendors Module <a class="header-anchor" href="#vendors-module" aria-label="Permalink to &quot;Vendors Module&quot;">​</a></h1><p>Phase 4 Purchasing module (Milestone 1) on the frozen platform. Mirrors the <a href="/user-guide/companies-overview">Companies</a> reference architecture — a workspace directory of suppliers, with assignment, notes, and an activity timeline. Vendors is the foundation for future <strong>Purchase Orders</strong> and <strong>Expenses</strong> modules.</p><h2 id="guides" tabindex="-1">Guides <a class="header-anchor" href="#guides" aria-label="Permalink to &quot;Guides&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Audience</th><th>Document</th></tr></thead><tbody><tr><td>Operators / workspace users</td><td><a href="/user-guide/vendors">vendors.md</a></td></tr><tr><td>Engineers</td><td><a href="/developer-guide/vendors">vendors-developer.md</a></td></tr><tr><td>Production / ops</td><td><a href="/deployment/vendors">vendors-production.md</a></td></tr><tr><td>Module Development Standard</td><td><a href="/developer-guide/module-development">module-development.md</a></td></tr><tr><td>Reference blueprint</td><td><a href="/user-guide/companies-overview">companies.md</a></td></tr><tr><td>Tenant API</td><td><a href="/api/tenant-v1-vendors">../api/tenant-v1-vendors.md</a></td></tr></tbody></table><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h2><ul><li>Name, email, phone, website, address, tax ID, payment terms, currency, status (active/inactive)</li><li>Assignment (<code>created_by</code> / <code>assigned_to</code>) with assignee scoping via <code>vendors.assign</code></li><li>Notes (comments) + activity timeline</li><li>Table view with search (including tax ID), status filter, and <strong>My Vendors</strong> toggle</li><li>KPIs via <code>GET /vendors/stats</code> (total, my vendors, unassigned, active, inactive)</li><li>Trash filtering plus <strong>Restore</strong> and <strong>Delete permanently</strong></li><li>Module licensing (<code>module:vendors</code>) + Spatie permissions — <strong>free Marketplace opt-in</strong></li><li>Audit + activity logging</li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p><code>vendors.view</code> · <code>create</code> · <code>update</code> · <code>delete</code> · <code>restore</code> · <code>force.delete</code> · <code>assign</code></p><p>Enable Vendors from Marketplace (free). Catalog: slug <code>vendors</code>, category <code>purchasing</code> (Purchasing), <code>is_default_included = false</code>, <code>is_billable = false</code>, <code>sort_order = 10</code>. Only Leads and Tasks install automatically on new workspaces.</p><h2 id="no-contacts-relationship" tabindex="-1">No contacts relationship <a class="header-anchor" href="#no-contacts-relationship" aria-label="Permalink to &quot;No contacts relationship&quot;">​</a></h2><p>Unlike Companies, Vendors do <strong>not</strong> link to Contacts. Vendors is a standalone supplier directory record.</p><h2 id="explicitly-deferred" tabindex="-1">Explicitly deferred <a class="header-anchor" href="#explicitly-deferred" aria-label="Permalink to &quot;Explicitly deferred&quot;">​</a></h2><ul><li>Purchase Orders (Phase 4 Milestone 2)</li><li>Expenses (Phase 4 Milestone 3)</li><li>Vendor scorecards / performance tracking</li><li>Vendor portal / self-service</li><li>Vendor import/export</li><li>Dashboard widgets for Vendors</li></ul>',13)])])}const h=t(i,[["render",s]]);export{m as __pageData,h as default};
